INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('love_in_allah', 'state', '«أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ»', 'Moge Degene omwille van Wie jij mij liefhebt, jou liefhebben — het antwoord op: ik heb jou lief omwille van Allaah (innie uhibbuka fi-llaah).', 'May the One for whose sake you love me, love you — the reply to: I love you for the sake of Allaah (innee uhibbuka fillaah).', 'والسنة أن من أحب أخاه في الله أعلمه بذلك، فيجيبه المُخبَر بهذا الدعاء.', 'De soennah is dat wie zijn broeder omwille van Allaah liefheeft, hem dat laat weten; de aangesprokene antwoordt dan met deze smeekbede.', 'The sunnah is that whoever loves his brother for Allaah''s sake informs him; the one told then responds with this supplication.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'يجيبه', 'toestand', 'state/situation', 1, 261),('loan_repay', 'state', '«بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ»', 'Moge Allaah jou zegenen in je gezin en je bezit; de beloning van een lening is immers dank en terugbetaling.', 'May Allaah bless you in your family and your wealth; the reward of a loan is only praise and repayment.', 'فيجمع المقترض عند القضاء بين حسن الأداء والدعاء لصاحب المعروف والثناء عليه.', 'De lener combineert bij de aflossing het goed terugbetalen, de smeekbede voor de weldoener en de lof over hem.', 'The borrower combines, at repayment, good repayment, supplication for the benefactor, and praise of him.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'يقول لمن أقرضه عند الوفاء', 'toestand', 'state/situation', 1, 262),('zakat', 'event', '«اللَّهُمَّ صَلِّ عَلَى آلِ فُلَانٍ»', 'O Allaah, schenk Uw gebeden aan de familie van die-en-die — de smeekbede voor wie zijn zakaat of sadaqah afdraagt.', 'O Allaah, send Your blessings upon the family of so-and-so — the supplication for the one who pays his zakaah or charity.', 'فيدعو آخذ الزكاة ــ الساعي والجهة والفقير ــ لمؤديها بهذا أو بنحوه من الدعاء بالبركة.', 'De ontvanger van de zakaat — de inzamelaar, de instantie en de arme — smeekt voor wie haar afdraagt met dit of soortgelijke smeekbede om zegen.', 'The recipient of zakaah — the collector, the authority and the poor — supplicates for the one paying it with this or similar supplication for blessing.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء لمن أدى صدقته', 'eredienst', 'act of worship', 1, 263),('hidden_shirk', 'state', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ»', 'O Allaah, ik zoek toevlucht bij U ertegen dat ik bewust iets aan U toeken (shirk pleeg), en ik vraag U om vergeving voor wat ik onbewust doe.', 'O Allaah, I seek refuge in You from knowingly associating anything with You, and I seek Your forgiveness for what I do unknowingly.', 'علّمه النبي صلى الله عليه وسلم أصحابه لما أخبرهم أن الشرك فيهم أخفى من دبيب النمل، وأنه يذهب صغير الشرك وكبيره؛ فيقال في كل يوم ويتأكد عند خوف الرياء في العمل.', 'De Profeet (vrede en zegeningen zij met hem) onderwees het zijn metgezellen toen hij hun meedeelde dat shirk onder hen verborgener is dan het kruipen van de mier, en dat het de kleine en de grote (shirk) wegneemt.', 'The Prophet (peace and blessings be upon him) taught it his companions when he informed them that shirk among them is more hidden than the crawling of an ant, and that it removes the minor and major (shirk).', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من الشرك الخفي', 'toestand', 'state/situation', 1, 264),('hajj', 'event', '«مَا مِنْ أَيَّامٍ أَعْظَمُ عِنْدَ اللَّهِ وَلَا أَحَبُّ إِلَيْهِ الْعَمَلُ فِيهِنَّ مِنْ هَذِهِ الْأَيَّامِ الْعَشْرِ؛ فَأَكْثِرُوا فِيهِنَّ مِنَ التَّهْلِيلِ وَالتَّكْبِيرِ وَالتَّحْمِيدِ»', 'Er zijn geen dagen waarop goede daden Allaah liever zijn dan deze tien dagen; verricht daarin dus veelvuldig tahliel, takbier en tahmied.', 'No days are dearer to Allaah for good deeds than these ten; so abound therein in tahleel, takbeer and tahmeed.', 'فيكثر في العشر من: لا إله إلا الله، والله أكبر، والحمد لله، جهرا في البيوت والأسواق والطرقات.', 'Men vermeerdert in de tien dagen: ''laa ilaaha illa-llaah, Allaahu akbar, al-hamdu li-llaah'', hoorbaar in de huizen, op de markten en de wegen.', 'One increases in the ten days: ''laa ilaaha illa-llaah, Allaahu akbar, al-hamdu lillaah'', audibly in the homes, markets and roads.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الإكثار من الذكر في العشر', 'eredienst', 'act of worship', 1, 265),('hajj', 'event', '«كَانَ ابْنُ عُمَرَ وَأَبُو هُرَيْرَةَ يَخْرُجَانِ إِلَى السُّوقِ فِي أَيَّامِ الْعَشْرِ يُكَبِّرَانِ، وَيُكَبِّرُ النَّاسُ بِتَكْبِيرِهِمَا»', 'Ibn 3umar en Aboe Hurayrah gingen in de tien dagen naar de markt terwijl zij takbier zeiden, en de mensen zeiden takbier met hun takbier mee.', 'Ibn Umar and Aboo Hurayrah would go to the market in the ten days saying takbeer, and the people would say takbeer with theirs.', 'فيه مشروعية الجهر بالتكبير المطلق في الأسواق والمجامع أيام العشر، وتذكير الناس به.', 'Hierin ligt de wettigheid van het hoorbaar zeggen van de onbeperkte takbier op de markten en samenkomsten in de tien dagen, en het de mensen eraan herinneren.', 'In it lies the legitimacy of saying the unrestricted takbeer aloud in the markets and gatherings in the ten days, and reminding people of it.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التكبير في عشر ذي الحجة', 'eredienst', 'act of worship', 1, 266),('hajj', 'event', '«كَانَ عُمَرُ يُكَبِّرُ فِي قُبَّتِهِ بِمِنًى، فَيَسْمَعُهُ أَهْلُ الْمَسْجِدِ فَيُكَبِّرُونَ، وَيُكَبِّرُ أَهْلُ الْأَسْوَاقِ، حَتَّى تَرْتَجَّ مِنًى تَكْبِيرًا»', '3umar zei de takbeer in zijn tent te Minaa; de mensen in de moskee hoorden hem en zeiden dan de takbeer, en de mensen in de markten zeiden de takbeer, totdat Minaa daverde van de takbeer.', '', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التكبير في أيام التشريق', 'eredienst', 'act of worship', 1, 267),('hajj', 'event', '«اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ كَبِيرًا»', 'Allaah is de Grootste, Allaah is de Grootste, Allaah is waarlijk de Grootste (de formule van Salmaan).', 'Allaah is the Greatest, Allaah is the Greatest, Allaah is truly the Greatest (the formula of Salmaan).', 'ومنها صيغة ابن مسعود رضي الله عنه المتقدمة في باب أذكار الصلوات الخاصة: «الله أكبر الله أكبر، لا إله إلا الله، والله أكبر الله أكبر، ولله الحمد».', 'Waaronder de eerder genoemde formule van Ibn Mas3oed (moge Allaah tevreden over hem zijn) in het hoofdstuk van de speciale gebeden: ''Allaahu akbar, Allaahu akbar, laa ilaaha illa-llaah...''.', 'Including the aforementioned formula of Ibn Mas3ood (may Allaah be pleased with him) in the chapter of special prayers: ''Allaahu akbar, Allaahu akbar, laa ilaaha illa-llaah...''.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'صيغة التكبير', 'eredienst', 'act of worship', 1, 268),('hajj', 'event', 'يكبر من صلاة الفجر يوم عرفة إلى صلاة العصر من آخر أيام التشريق', 'De gebonden takbier: na elk verplicht gebed, vanaf fadjr van de dag van 3arafah tot en met 3asr van de laatste dag van de tashrieq-dagen.', 'The restricted takbeer: after every obligatory prayer, from fajr of the day of Arafah until asr of the last day of tashreeq.', 'فيجمع في هذه الأيام بين التكبير المطلق في عموم الوقت والمقيد بأدبار المكتوبات على أثر علي وابن مسعود.', 'Men combineert in deze dagen de onbeperkte takbier gedurende de gehele tijd en de gebonden takbier na de verplichte gebeden, naar de overlevering van 3alie en Ibn Mas3oed.', 'One combines in these days the unrestricted takbeer throughout the time and the restricted takbeer after the obligatory prayers, per the narration of 3alee and Ibn Mas3ood.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التكبير المقيّد أيام التشريق', 'eredienst', 'act of worship', 1, 269),('menses', 'state', 'تأتي الحائض والنفساء بجميع الأذكار: أذكار الطرفين والنوم والوقائع كلها، والتسبيح والتهليل والدعاء', 'De menstruerende en de kraamvrouw verrichten alle vormen van dhikr en du3aa'': de adhkaar van ochtend en avond, van het slapen en van alle gelegenheden; haar toestand belet dit niet.', 'The menstruating and postnatal woman performs all forms of dhikr and du3aa'': the adhkaar of morning and evening, of sleep and of all occasions; her state does not prevent this.', 'فلا تعطل المرأة أورادها أيام عذرها؛ فإن حيضتها ليست في يدها ولا لسانها.', 'De vrouw staakt haar wird dus niet in de dagen van haar excuus; want haar menstruatie ligt niet in haar hand noch op haar tong.', 'So the woman does not suspend her wird in the days of her excuse; for her menstruation is not in her hand nor on her tongue.', 'لم يرد فيه أجر مخصوص، وفيه رفع الحرج عنها.', 'Er is geen specifieke beloning voor overgeleverd, daarin ligt het wegnemen van de belemmering voor haar.', 'No specific reward is reported, in it is the removal of hardship for her.', 'الحيض لا يمنع شيئا من الذكر', 'toestand', 'state/situation', 1, 270),('menses', 'state', 'تلبي الحائض وتذكر وتدعو في نسكها كله إلا الطواف، وتخرج للعيد فتكبّر مع الناس وتشهد الدعوة وتعتزل المصلى', 'De menstruerende vrouw zegt de talbiyah en verricht alle dhikr en smeekbeden van de bedevaart behalve de tawaaf, en zij gaat mee naar het feestgebed: zij zegt takbier met de mensen mee en woont het goede bij, maar mijdt de gebedsplaats zelf.', 'The menstruating woman says the talbiyah and performs all remembrance and supplication of the pilgrimage except tawaaf, and attends the Eid: saying takbeer with the people and witnessing the good, while keeping off the prayer-ground itself.', 'وفي فعل نساء الصحابة رضي الله عنهن شاهد التطبيق: كنّ يخرجن حُيَّضا يكبّرن بتكبير الناس ويرجون بركة اليوم.', 'In het doen van de vrouwelijke metgezellen (moge Allaah tevreden over hen zijn) ligt het toepassingsbewijs: zij gingen menstruerend uit, zeiden takbier met de mensen mee en hoopten op de zegen (van de dag).', 'In the doing of the female companions (may Allaah be pleased with them) is the proof of application: they went out menstruating, said takbeer with the people and hoped for the blessing (of the day).', 'شهود الخير ودعوة المسلمين منصوص في الحديث.', 'Het bijwonen van het goede en de smeekbede van de moslims is uitdrukkelijk in de hadieth.', 'Witnessing the good and the supplication of the Muslims is stated in the hadeeth.', 'وتذكر الله في النسك وتشهد الخير', 'toestand', 'state/situation', 1, 271),('daily_rules', 'general', 'يستحضر المؤمن النية في عاداته كلها ــ نومه وأكله وكسبه ومباشرته أهله ــ فتنقلب عبادات', 'De gelovige neemt in al zijn gewoonten — slapen, eten, werken en de omgang met zijn gezin — de intentie mee, zodat zij aanbidding worden.', 'The believer carries intention into all his habits — sleep, food, work and marital life — so they become worship.', 'أول ما يُصلح المؤمن في يومه قلبه: لمن يستيقظ؟ ولمن يخرج ويكدح؟', 'Het eerste wat de gelovige in zijn dag in orde brengt is zijn hart: voor wie ontwaakt hij? En voor wie gaat hij uit en zwoegt hij?', 'The first thing the believer sets right in his day is his heart: for whom does he wake? And for whom does he go out and toil?', 'الفضل مبين: لكل امرئ ما نوى؛ فمن نوى بالمباح التقوي على الطاعة أُجر عليه.', 'De verdienste is toegelicht: ieder krijgt wat hij beoogde; wie met het toegestane beoogt zich te sterken op de gehoorzaamheid, wordt daarvoor beloond.', 'The merit is explained: everyone gets what he intended; whoever intends by the permissible to strengthen himself for obedience is rewarded for it.', 'استحضار النية في العادات', 'methodische richtlijn', 'methodological guideline', 1, 272),('daily_rules', 'general', 'الفرائض العينية اليومية: الصلوات الخمس بشروطها، وأداء حقوق العباد الواجبة، واجتناب المحرمات؛ وما وراءها تطوع يتفاضل', 'De dagelijkse individuele verplichtingen: de vijf gebeden met hun voorwaarden, het nakomen van de verplichte rechten van de mensen en het vermijden van het verbodene; daarboven is alles vrijwillige toenadering.', 'The daily individual obligations: the five prayers with their conditions, fulfilling people''s due rights, and avoiding the forbidden; beyond that all is voluntary devotion.', 'يحفظ المؤمن الحد الأدنى الواجب أولا، ثم يرقى في التطوع بقدر همته من غير غلو ولا انقطاع.', 'De gelovige bewaart eerst het verplichte minimum, en stijgt dan in het vrijwillige naar de mate van zijn ijver, zonder overdrijving en zonder onderbreking.', 'The believer first preserves the obligatory minimum, then rises in the voluntary to the measure of his zeal, without excess or interruption.', 'وفي الحديث القدسي: «وما تقرب إلي عبدي بشيء أحب إلي مما افترضت عليه، وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه» [البخاري (6502)].', 'In de heilige hadieth: ''Mijn dienaar nadert Mij met niets liefeers dan wat Ik hem heb verplicht, en Mijn dienaar blijft Mij naderen met vrijwillige daden totdat Ik hem liefheb.''', 'In the sacred hadeeth: ''My servant draws near to Me with nothing dearer than what I made obligatory, and My servant keeps drawing near to Me with voluntary acts until I love him.''', 'الفرائض العينية اليومية', 'methodische richtlijn', 'methodological guideline', 1, 273),('daily_rules', 'general', 'يفتتح المؤمن نهاره بنية أداء صدقة كل مفصل من مفاصله الثلاثمائة والستين: ذكرا وإصلاحا ونفقة، أو يجزئه عنها ركعتا الضحى', 'Men opent zijn dag met de intentie de sadaqah van elk gewricht te voldoen: dhikr, goed gebieden en weldoen; en twee rak3ah in de duhaa volstaan daarvoor.', 'One opens his day intending the charity due from every joint: dhikr, enjoining good and kindness; and two rak3ahs of duhaa suffice for it.', 'من ضاق وقته عن كثرة الذكر والصدقة كفته ركعتا الضحى عن صدقة يومه.', 'Wie te weinig tijd heeft voor veel dhikr en liefdadigheid, aan hem volstaan de twee rak3ah van de duhaa voor de sadaqah van zijn dag.', 'Whoever lacks time for much dhikr and charity, the two rak3ahs of duhaa suffice him for the charity of his day.', 'الفضل منصوص: صدقة عن كل سلامى، وفي رواية مسلم (1006): «وفي بُضع أحدكم صدقة».', 'De verdienste is uitdrukkelijk: een sadaqah voor elk gewricht, en in Muslims overlevering (1006): ''en in de echtelijke gemeenschap van een van jullie is een sadaqah''.', 'The merit is stated: a charity for every joint, and in Muslim''s narration (1006): ''and in the marital relation of one of you is a charity''.', 'افتتاح النهار بصدقة المفاصل', 'methodische richtlijn', 'methodological guideline', 1, 274),('daily_rules', 'general', 'يوزع المؤمن يومه على الحقوق: حق الله بالفرائض والورد، وحق النفس بالنوم والقوت، وحق الأهل بالعشرة والنفقة؛ ولا يطغي حقا على حق', 'Men verdeelt zijn dag over de rechten: het recht van Allaah, het recht van de eigen ziel en het recht van het gezin — en geeft ieder rechthebbende zijn recht.', 'One divides his day among the rights: the right of Allaah, of one''s own soul and of one''s family — giving each claimant his due.', 'ومنه فقه سلمان: نومُ أول الليل ليقوى على قيام آخره خير من قيام يعقبه تضييع.', 'Waaronder het begrip van Salmaan: slaap in het eerste deel van de nacht om sterk te zijn voor het staan in het laatste deel is beter dan een nachtwake gevolgd door verwaarlozing.', 'Including the understanding of Salmaan: sleep in the first part of the night to be strong for standing in the last is better than a vigil followed by neglect.', 'أقره النبي صلى الله عليه وسلم بقوله: «صدق سلمان»؛ فصار شرعا.', 'De Profeet (vrede en zegeningen zij met hem) bevestigde het met zijn woord ''Salmaan heeft gelijk''; zo werd het wet.', 'The Prophet (peace and blessings be upon him) confirmed it with his words ''Salmaan has spoken truly''; thus it became law.', 'توزيع اليوم على الحقوق', 'methodische richtlijn', 'methodological guideline', 1, 275),('pre_fajr', 'time', 'ذكر التعارّ ودعاؤه، تقدم بمتنه في باب الاستيقاظ [البخاري (1154)]', 'De dhikr van het nachtelijk ontwaken; de tekst staat bij het hoofdstuk van het ontwaken.', 'The dhikr of stirring at night; its text is under the waking chapter.', 'من انتبه ولو لحظة اغتنمها بالذكر المتقدم ثم الدعاء.', 'Wie ook maar een ogenblik wakker wordt, benut het met de eerder genoemde dhikr, gevolgd door smeekbede.', 'Whoever wakes even for a moment seizes it with the aforementioned dhikr, followed by supplication.', 'استجابة الدعاء وقبول الصلاة كما تقدم نصا.', 'De verhoring van de smeekbede en de aanvaarding van het gebed, zoals eerder uitdrukkelijk vermeld.', 'The answering of supplication and acceptance of prayer, as previously stated explicitly.', 'ذكر التعارّ ودعاؤه', 'tijdstip', 'time', 1, 276),('pre_fajr', 'time', 'ركعات يفتتحها بركعتين خفيفتين، مثنى مثنى، بالاستفتاحات المتقدمة في بابه، وأفضله ثلث الليل الآخر ساعة النزول الإلهي', 'Het nachtgebed: geopend met twee lichte rak3ah, twee aan twee, met de eerder genoemde openingssmeekbeden; het beste deel is het laatste derde van de nacht.', 'The night prayer: opened with two light rak3ahs, two by two, with the aforementioned opening supplications; its best part is the last third of the night.', 'من غلبه النوم عنه صلى من النهار ثنتي عشرة ركعة كما كان صلى الله عليه وسلم يفعل [مسلم (746)].', 'Wie door slaap ervan wordt overmand, bidt overdag twaalf rak3ah zoals hij (vrede en zegeningen zij met hem) deed [Muslim 746].', 'Whoever is overcome by sleep from it prays twelve rak3ahs by day as he (peace and blessings be upon him) did [Muslim 746].', '«أفضل الصلاة بعد الفريضة»، وهو دأب الصالحين ومطردة للداء عن الجسد.', '''Het beste gebed na het verplichte'', het is de gewoonte van de rechtschapenen en verdrijft de ziekte van het lichaam.', '''The best prayer after the obligatory'', it is the practice of the righteous and repels illness from the body.', 'صلاة الليل وركعتاها الخفيفتان', 'tijdstip', 'time', 1, 277),('pre_fajr', 'time', 'ركعة فأكثر، بقنوته وذكر ما بعده المتقدمين في بابه، ووقته من بعد العشاء إلى الفجر', 'Het witr-gebed: één rak3ah of meer, met zijn qunoet en de dhikr erna; zijn tijd is van na 3ishaa'' tot fadjr.', 'The witr prayer: one rak3ah or more, with its qunoot and the dhikr after it; its time is from after 3ishaa'' until fajr.', 'من خاف ألا يقوم آخر الليل أوتر أوله؛ لحديث: «من خاف أن لا يقوم من آخر الليل فليوتر أوله» [مسلم (755)].', 'Wie vreest niet in het laatste deel van de nacht op te staan, verricht de witr in het begin ervan; wegens de hadieth: ''wie vreest niet op te staan aan het einde van de nacht, laat hem in het begin de witr verrichten'' [Muslim 755].', 'Whoever fears not rising in the last part of the night performs the witr at its start; per the hadeeth: ''whoever fears not rising at the night''s end, let him perform witr at its start'' [Muslim 755].', 'وفي مسلم (755): «وصلاة آخر الليل مشهودة، وذلك أفضل».', 'In Muslim (755): ''En het gebed in het laatste deel van de nacht wordt bijgewoond, en dat is beter.''', 'In Muslim (755): ''And the prayer in the latter part of the night is witnessed, and that is better.''', 'الوتر وقنوته', 'tijdstip', 'time', 1, 278),('pre_fajr', 'time', 'سحور خفيف ولو جرعة ماء، والإكثار من الاستغفار في السحَر', 'Een lichte suhoer, al is het een slok water, en veelvuldige istighfaar in de laatste nachtdelen.', 'A light suhoor, even a sip of water, and abundant istighfaar in the pre-dawn hours.', 'يجمع القائم بين ختم قيامه بالوتر والاستغفار حتى يطلع الفجر.', 'De nachtbidder combineert het afsluiten van zijn nachtwake met de witr en de istighfaar tot de dageraad aanbreekt.', 'The night-worshipper combines sealing his vigil with the witr and istighfaar until dawn breaks.', '«فإن في السحور بركة»، وثناء الله على أهل الأسحار.', '''Waarlijk, in de suhoer is zegen'', en Allaahs lof voor de mensen van de laatste nachtdelen.', '''Indeed, in the suhoor is blessing'', and Allaah''s praise for the people of the pre-dawn hours.', 'السحور والاستغفار في السحَر', 'tijdstip', 'time', 1, 279),('fajr_period', 'time', 'ركعتان خفيفتان قبل الفريضة، يقرأ فيهما بالكافرون والإخلاص أو بآيتي البقرة وآل عمران [مسلم (727)]', 'Twee lichte rak3ah vóór het fadjr-gebed, met al-Kaafiroen en al-Ikhlaas of de twee bekende verzen — beter dan de wereld en al wat erin is.', 'Two light rak3ahs before fajr, with al-Kaafiroon and al-Ikhlaas or the two known verses — better than the world and all it contains.', 'يخففهما، ويضطجع بعدهما على شقه الأيمن إن كان في بيته كما كان يفعل صلى الله عليه وسلم [البخاري (1160)].', 'Men maakt ze licht en gaat er daarna op de rechterzij bij liggen als men thuis is, zoals hij (vrede en zegeningen zij met hem) deed [al-Bukhaarie 1160].', 'One makes them light then lies on the right side after them if at home, as he (peace and blessings be upon him) did [al-Bukhaaree 1160].', 'الفضل منصوص: خير من الدنيا وما فيها.', 'De verdienste is uitdrukkelijk: beter dan de wereld en al wat erin is.', 'The merit is stated: better than the world and all it contains.', 'سنة الفجر القبلية', 'tijdstip', 'time', 1, 280);